import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Home, Eye, EyeOff } from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import './Auth.css';

const DEMO_USERS = [
  { email: 'admin@propconnect.co.za', password: 'admin123', role: 'admin', name: 'Admin User' },
  { email: 'sarah@propconnect.co.za', password: 'agent123', role: 'agent', name: 'Sarah Dlamini', agentId: 1 },
  { email: 'client@email.com', password: 'client123', role: 'client', name: 'Thabo Mokoena' },
];

export default function Login() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const [form, setForm] = useState({ email: '', password: '' });
  const [showPw, setShowPw] = useState(false);
  const [error, setError] = useState('');

  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  const handleSubmit = (e) => {
    e.preventDefault();
    const user = DEMO_USERS.find(u => u.email === form.email && u.password === form.password);
    if (!user) { setError('Invalid email or password.'); return; }
    login(user);
    if (user.role === 'admin') navigate('/admin');
    else if (user.role === 'agent') navigate('/agent');
    else navigate('/client');
  };

  const quickLogin = (u) => {
    login(u);
    if (u.role === 'admin') navigate('/admin');
    else if (u.role === 'agent') navigate('/agent');
    else navigate('/client');
  };

  return (
    <div className="auth-page">
      <div className="auth-card">
        <div className="auth-brand">
          <Home size={28} />
          <span>Prop<strong>Connect</strong></span>
        </div>
        <h1>Welcome back</h1>
        <p className="auth-sub">Sign in to your account to continue</p>

        {error && <div className="alert alert-error">{error}</div>}

        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label>Email Address</label>
            <input className="form-control" type="email" required value={form.email} onChange={e => set('email', e.target.value)} placeholder="your@email.com" autoComplete="email" />
          </div>
          <div className="form-group">
            <label>Password</label>
            <div className="pw-wrap">
              <input className="form-control" type={showPw ? 'text' : 'password'} required value={form.password} onChange={e => set('password', e.target.value)} placeholder="••••••••" autoComplete="current-password" />
              <button type="button" className="pw-toggle" onClick={() => setShowPw(!showPw)}>
                {showPw ? <EyeOff size={16} /> : <Eye size={16} />}
              </button>
            </div>
          </div>
          <button type="submit" className="btn btn-primary auth-submit">Sign In</button>
        </form>

        <div className="auth-divider"><span>or try a demo account</span></div>

        <div className="demo-accounts">
          {DEMO_USERS.map(u => (
            <button key={u.role} className="demo-btn" onClick={() => quickLogin(u)}>
              <div className={`demo-role-badge role-${u.role}`}>{u.role}</div>
              <div>
                <div className="demo-name">{u.name}</div>
                <div className="demo-email">{u.email}</div>
              </div>
            </button>
          ))}
        </div>

        <p className="auth-footer">Don't have an account? <Link to="/register">Register here</Link></p>
      </div>
    </div>
  );
}
